  "query": "select schemaname, relname, n_live_tup, n_dead_tup, round(100.0*n_dead_tup/greatest(n_live_tup+n_dead_tup,1),2) as dead_pct, last_vacuum, last_autovacuum, vacuum_count, autovacuum_count, analyze_count, autoanalyze_count from pg_stat_user_tables order by n_dead_tup desc limit 30;"
}

